#include <iostream>
#include <cstdio>
#include <cstdlib>

#include <algorithm>
#include <utility>
#include <cmath>
#include <ctime>
#include <functional>
#include <string.h>
#include <cctype>

#include <string>
#include <vector>
#include <map>
#include <set>
#include <queue>
#include <stack>
using namespace std;

#define sqr(a) ((a) * (a))

struct circle {
    double x, y, r;
};

circle c(double _x, double _y, double _r) {
    circle ci;
    ci.x = _x;
    ci.y = _y;
    ci.r = _r;
    return ci;
}

vector<circle> v;

bool interact(circle a, circle b) {
    if (sqrt(sqr(a.x - b.x) + sqr(a.y - b.y)) + min(a.r, b.r) <= max(a.r, b.r)
            || sqrt(sqr(a.x - b.x) + sqr(a.y - b.y)) >= a.r + b.r) {
        return false;
    }
    return true;
}

bool isIn(circle a, circle b, circle c) {
    if (sqrt(sqr(a.x - b.x) + sqr(a.y - b.y)) <= min(b.r, c.r)
            && (a.r >= min(b.r, c.r) && a.r <= max(b.r, c.r))) {
        return true;
    }
    return false;
}

int main() {
    double x, y, r;
    for (int i = 0; i < 2; i++) {
        cin >> x >> y;
        for (int j = 0; j < 2; j++) {
            cin >> r;
            v.push_back(c(x, y, r));
        }
    }

    int ans = 0;
    for (int i = 0; i < static_cast<int>(v.size()); i++) {
        bool flag = true;
        for (int j = 0; j < static_cast<int>(v.size()); j++) {
            if (i != j && interact(v[i], v[j])) {
                flag = false;
            }
        }
        if (isIn(v[i], v[i <= 1 ? 2 : 0], v[i <= 1 ? 3 : 1])) {
            flag = false;
        }
        if (flag) {
            ans++;
        }
    }

    cout << ans;
    return 0;
}

